  let numCcs = V;
  for (let u = 0; u < V; u++) {
    uf.add(u);
  }
  let mstCost = 0;
  edges.sort((a, b) => a[2] - b[2]);

  for (const [u, v, weight] of edges) {
    const reprU = uf.find(u);
